package com.aurelia.pms;
import android.app.Activity;import android.content.Intent;import android.net.Uri;import android.os.Bundle;import android.util.Base64;import android.util.Log;import android.webkit.JavascriptInterface;import android.webkit.ValueCallback;import android.webkit.WebChromeClient;import android.webkit.WebView;import android.webkit.WebViewClient;import android.graphics.Bitmap;import android.graphics.BitmapFactory;import org.json.JSONObject;import com.google.mlkit.vision.common.InputImage;import com.google.mlkit.vision.text.Text;import com.google.mlkit.vision.text.TextRecognition;import com.google.mlkit.vision.text.TextRecognizer;import com.google.mlkit.vision.text.latin.TextRecognizerOptions;import java.util.regex.Matcher;import java.util.regex.Pattern;
public class MainActivity extends Activity {private static final int FILE_PICKER=4182;private WebView webView;private ValueCallback<Uri[]> fileCallback;private final TextRecognizer recognizer=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);
@Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);webView=findViewById(R.id.webview);webView.getSettings().setJavaScriptEnabled(true);webView.getSettings().setDomStorageEnabled(true);webView.getSettings().setAllowFileAccess(true);webView.getSettings().setAllowContentAccess(true);webView.setWebViewClient(new WebViewClient());webView.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=cb;try{startActivityForResult(p.createIntent(),FILE_PICKER);}catch(Exception e){fileCallback=null;cb.onReceiveValue(null);return false;}return true;}});webView.addJavascriptInterface(new NativeBridge(),"AureliaNative");webView.loadUrl("file:///android_asset/index.html");}
private class NativeBridge{@JavascriptInterface public void postMessage(String raw){try{JSONObject q=new JSONObject(raw);if(!"recognizeId".equals(q.optString("type")))return;String id=q.optString("requestId");byte[] data=Base64.decode(q.optString("data"),Base64.DEFAULT);Bitmap bmp=BitmapFactory.decodeByteArray(data,0,data.length);if(bmp==null){send(id,new JSONObject().put("text",""));return;}recognizer.process(InputImage.fromBitmap(bmp,0)).addOnSuccessListener(t->{try{send(id,parse(t));}catch(Exception e){send(id,new JSONObject().put("text",t.getText()));}finally{bmp.recycle();}}).addOnFailureListener(e->{try{send(id,new JSONObject().put("text",""));}catch(Exception ignored){}finally{bmp.recycle();}});}catch(Exception e){Log.e("AureliaPMS","OCR request failed",e);}}}
private JSONObject parse(Text result)throws Exception{String text=result.getText()==null?"":result.getText(),name="",id="";for(String line:text.split("\\R")){String t=line.trim();if(name.isEmpty()&&t.matches("(?i)^(name|surname|given names?)\\s*[:.-]?\\s*.+"))name=t.replaceFirst("(?i)^(name|surname|given names?)\\s*[:.-]?\\s*","").trim();if(id.isEmpty()&&t.matches("(?i).*(?:[A-Z]{1,3}[- ]?\\d[A-Z0-9/-]{4,}|\\b\\d{6,}\\b).*")){Matcher m=Pattern.compile("(?i)[A-Z0-9/-]{5,}").matcher(t);while(m.find()){String c=m.group();if(c.matches(".*\\d.*")){id=c;break;}}}}if(name.isEmpty())for(String line:text.split("\\R")){String t=line.trim();if(t.matches("[A-Z][A-Z ,.'-]{5,}")&&!t.matches("(?i).*(GOVERNMENT|REPUBLIC|AUTHORITY|IDENTITY|NATIONAL|PASSPORT|DRIVING|LICENCE|LICENSE|DATE OF BIRTH).*")){name=t;break;}}return new JSONObject().put("fullName",name).put("idNumber",id).put("text",text);}
private void send(String id,JSONObject payload){String js="window.aureliaNativeOcrResult&&window.aureliaNativeOcrResult("+JSONObject.quote(id)+","+JSONObject.quote(payload.toString())+");";runOnUiThread(()->webView.evaluateJavascript(js,null));}
@Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==FILE_PICKER&&fileCallback!=null){fileCallback.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(c,d));fileCallback=null;}}
@Override public void onBackPressed(){if(webView!=null&&webView.canGoBack())webView.goBack();else super.onBackPressed();}@Override protected void onDestroy(){recognizer.close();if(webView!=null)webView.destroy();super.onDestroy();}}
